package fr.elementa.mine;
import org.bukkit.*; import org.bukkit.event.*; import world.bentobox.bentobox.api.events.island.IslandEvent; import world.bentobox.bentobox.database.objects.Island;
public final class IslandListener implements Listener { private final ElementaMine p; private final MineManager mm; public IslandListener(ElementaMine p,MineManager mm){this.p=p;this.mm=mm;}
 @EventHandler public void onIsland(IslandEvent e){if(e.getReason()!=IslandEvent.Reason.CREATED||e.getIsland()==null)return; Island i=e.getIsland(); if(i.getWorld()==null||i.getCenter()==null)return; String id=i.getUniqueId().toString(); int cx=i.getCenter().getBlockX()+p.getConfig().getInt("mine.offset-x"),cz=i.getCenter().getBlockZ()+p.getConfig().getInt("mine.offset-z"); int size=MineTiers.size(p,1), y=p.getConfig().getInt("mine.y-center",69), r=size/2; MineRegion m=mm.getOrCreate(id);m.setTier(1);m.setPos1(new Location(i.getWorld(),cx-r,y-r,cz-r));m.setPos2(new Location(i.getWorld(),cx+r,y+r,cz+r));m.setComposition(MineTiers.composition(p));m.setResetThreshold(p.getConfig().getInt("mine.reset-threshold",250));mm.generate(m);mm.saveAll();p.getLogger().info("Mine generee pour l'ile "+id); }
}
